{
  "name": "Medicare Premium Assistance Programs",
  "eligibility": {
    "age": null,
    "income_limits": {
      "programs": [
        {
          "name": "QMB (Qualified Medicare Beneficiary)",
          "single": "$1,330/month",
          "couple": "$1,804/month",
          "basis": "About 100% of the Federal Poverty Level plus a $20 income disregard"
        },
        {
          "name": "SLMB (Specified Low-Income Medicare Beneficiary)",
          "single": "$1,596/month",
          "couple": "$2,164/month",
          "basis": "About 100% to 120% of the Federal Poverty Level plus a $20 income disregard"
        },
        {
          "name": "QI (Qualifying Individual)",
          "single": "$1,796/month",
          "couple": "$2,435/month",
          "basis": "About 120% to 135% of the Federal Poverty Level plus a $20 income disregard"
        },
        {
          "name": "QDWI (Qualified Disabled and Working Individuals)",
          "single": "$2,660/month",
          "couple": "$3,607/month",
          "basis": "For disabled working people under 65; different eligibility structure than QMB/SLMB/QI"
        }
      ],
      "notes": [
        "Income standards are measured monthly.",
        "The application is handled through Ohio Medicaid, and eligibility is determined using the Medicaid application."
      ]
    },
    "asset_limits": {
      "qmb_slmb_qi": {
        "single": "$9,950",
        "couple": "$14,910"
      },
      "qdwi": {
        "single": "$4,000",
        "couple": "$6,000"
      },
      "what_counts": [
        "Bank accounts",
        "Cash",
        "Retirement accounts",
        "Other countable resources used in Medicaid-style resource tests"
      ],
      "what_is_exempt": [
        "The home you live in is generally not counted",
        "Personal belongings are generally not counted",
        "One vehicle is generally not counted",
        "Some burial and life-insurance arrangements may be excluded under Medicaid-style rules"
      ],
      "notes": [
        "The source material indicates asset limits apply, but the exact countable/exempt treatment can follow Medicaid resource rules and may vary by program category."
      ]
    },
    "other_requirements": [
      "Must be entitled to Medicare Part A for most MSP categories",
      "Must live in Ohio",
      "Must meet the relevant income and resource limits",
      "QDWI is for certain disabled working individuals under age 65",
      "Eligibility is determined through a Medicaid application"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": [
      "QMB: pays Medicare Part A premiums, Part B premiums, deductibles, coinsurance, and copayments",
      "SLMB: pays Medicare Part B premium only",
      "QI: pays Medicare Part B premium only",
      "QDWI: pays Medicare Part A premium for qualifying working disabled individuals"
